package titus.expenseassistant;
import android.content.Context; import android.content.SharedPreferences; import android.security.keystore.KeyGenParameterSpec; import android.security.keystore.KeyProperties; import android.util.Base64; import java.nio.charset.StandardCharsets; import java.security.KeyStore; import javax.crypto.Cipher; import javax.crypto.KeyGenerator; import javax.crypto.SecretKey; import javax.crypto.spec.GCMParameterSpec;
final class SecretStore {
 private static final String ALIAS="expense_assistant_gemini_key"; private final SharedPreferences prefs; SecretStore(Context c){prefs=c.getSharedPreferences("secure_settings",Context.MODE_PRIVATE);} boolean hasApiKey(){return !getApiKey().isEmpty();}
 String getApiKey(){try{String v=prefs.getString("gemini_key","");if(v.isEmpty())return "";byte[] p=Base64.decode(v,Base64.NO_WRAP),iv=new byte[12],enc=new byte[p.length-12];System.arraycopy(p,0,iv,0,12);System.arraycopy(p,12,enc,0,enc.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));return new String(c.doFinal(enc),StandardCharsets.UTF_8);}catch(Exception e){return "";}}
 void setApiKey(String v){try{if(v.trim().isEmpty()){prefs.edit().remove("gemini_key").apply();return;}Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());byte[] enc=c.doFinal(v.trim().getBytes(StandardCharsets.UTF_8)),p=new byte[c.getIV().length+enc.length];System.arraycopy(c.getIV(),0,p,0,c.getIV().length);System.arraycopy(enc,0,p,c.getIV().length,enc.length);prefs.edit().putString("gemini_key",Base64.encodeToString(p,Base64.NO_WRAP)).apply();}catch(Exception ignored){}}
 private SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(ALIAS))return((KeyStore.SecretKeyEntry)ks.getEntry(ALIAS,null)).getSecretKey();KeyGenerator kg=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");kg.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return kg.generateKey();}
}
